function b64bytes(v){const raw=atob(String(v||''));return Uint8Array.from(raw,c=>c.charCodeAt(0))}function bytes64(bytes){let raw='';for(let i=0;i<bytes.length;i+=0x8000)raw+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(raw)}
