async function openInbox(id){activeInbox=ideaInbox.find(x=>String(x.id)===String(id));if(!activeInbox)return;const p=await artifactFor(activeInbox).catch(()=>({})),a=activeInbox.analysis||{};$('#inboxDialogTitle').textContent=a.suggestedTitle||activeInbox.title||captureTypeLabel(activeInbox);$('#inboxDetailStatus').textContent=inboxStatusLabel(activeInbox);$('#inboxDetailStatus').className='status-chip '+(activeInbox.status==='processing'?'working':activeInbox.status==='error'?'error':'');$('#inboxDetailMeta').innerHTML=`${sourceChip(activeInbox.sourceType||'own',captureTypeLabel(activeInbox))}<span>${esc(new Intl.DateTimeFormat('de-AT',{dateStyle:'medium',timeStyle:'short'}).format(new Date(activeInbox.createdAt||activeInbox.receivedAt)))}</span>`;const preview=$('#inboxSourcePreview'),photos=p.photos||[],audio=p.audio||[];preview.innerHTML=[...photos.slice(0,4).map(ph=>`<img src="data:${esc(ph.mime||'image/jpeg')};base64,${ph.dataBase64}" alt="Capture Original">`),...audio.slice(0,4).map((au,i)=>`<audio controls preload="metadata" src="data:${esc(au.mime||'audio/webm')};base64,${au.dataBase64}" aria-label="Originalaufnahme ${i+1}"></audio>`)].join('');const rawBody=String(p.noteText||activeInbox.body||'').trim();$('#inboxOriginalBody').innerHTML=rawBody?`<div class="original-text"><span>Originaltext</span><p>${esc(rawBody)}</p></div>`:'<p class="kh-muted">Kein zusätzlicher Originaltext.</p>';$('#inboxTranscriptBlock').hidden=!activeInbox.transcript;$('#inboxTranscript').textContent=activeInbox.transcript||'';const link=$('#inboxOriginalLink'),rawUrl=String(p.ideaSourceUrl||activeInbox.sourceUrl||'').trim(),safeUrl=safeExternalUrl(rawUrl);link.hidden=!rawUrl;link.innerHTML=rawUrl?`<span>Gespeicherter Link</span>${safeUrl?`<a href="${esc(safeUrl)}" target="_blank" rel="noopener noreferrer">${esc(rawUrl)}</a>`:`<p>${esc(rawUrl)}</p>`}`:'';const chips=v=>(v||[]).map(t=>`<span class="analysis-chip">${esc(t)}</span>`).join('');$('#inboxAiContent').innerHTML=Object.keys(a).length?`<div class="ai-result-field"><span>Vorgeschlagener Titel</span><strong>${esc(a.suggestedTitle||'—')}</strong></div><div class="ai-result-field"><span>Zusammenfassung</span><p>${esc(a.summary||'—')}</p></div><div class="ai-result-field"><span>Themen</span><div class="analysis-chip-row">${chips(a.topics)}</div></div><div class="ai-result-field"><span>Tags</span><div class="analysis-chip-row">${chips(a.tags)}</div></div><div class="ai-result-field"><span>Schlagworte</span><div class="analysis-chip-row">${chips(a.keywords)}</div></div>${a.uncertaintyNote?`<div class="ai-limit-note"><strong>${a.uncertain?'Prüfung empfohlen':'Hinweis'}</strong><p>${esc(a.uncertaintyNote)}</p></div>`:''}${(a.limitations||[]).length?`<div class="ai-limit-note"><strong>Lokale Grenzen</strong><p>${esc((a.limitations||[]).join(' '))}</p></div>`:''}${a.model?`<p class="kh-muted">Lokal analysiert mit ${esc(a.model)}</p>`:''}`:'<div class="kh-empty compact">Noch keine lokale Analyse.</div>';$('#inboxProcessing').textContent=activeInbox.status==='processing'?'Lokale Verarbeitung läuft im Hintergrund. Du kannst den Dialog schließen.':activeInbox.processingError?activeInbox.processingError:activeInbox.status==='new'?'Wartet auf lokale Verarbeitung.':'';$('#inboxArchive').textContent=activeInbox.archivedAt?'Wiederherstellen':'Archivieren';$('#promoteInbox').disabled=activeInbox.archivedAt||activeInbox.status==='processing';$('#inboxDialog').showModal()}
async function thumbnailFromActive(){try{const p=await artifactFor(activeInbox),ph=(p.photos||[])[0];if(!ph)return'';const src=`data:${ph.mime||'image/jpeg'};base64,${ph.dataBase64}`;if(src.length<150000)return src;return await new Promise(resolve=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,600/im.width),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.68).slice(0,175000))};im.onerror=()=>resolve('');im.src=src})}catch(_){return''}}
async function promoteInbox(){
  if(!activeInbox)return;
  const a=activeInbox.analysis||{},
    title=a.suggestedTitle||activeInbox.title||captureTypeLabel(activeInbox),
    body=[activeInbox.transcript,activeInbox.body].filter(Boolean).join('\n\n').trim(),
    sourceType=activeInbox.sourceType||'own',
    sourceUrl=activeInbox.sourceUrl||'',
    content=body?'<p>'+esc(body).replace(/\n\n+/g,'</p><p>').replace(/\n/g,'<br>')+'</p>':'';
  try{
    const saved=await postCloud('/admin/knowledge/save',{
      itemType:'idea',title,contentHtml:content,
      excerpt:(a.summary||body).slice(0,500),
      tags:a.tags||[],
      sources:sourceUrl?[{label:sourceType,url:sourceUrl}]:[]
    }),thumb=await thumbnailFromActive();
    await postCloud('/admin/knowledge/meta',{
      itemId:saved.item.id,kind:'idea',stage:'ideas',
      cluster:(a.topics||[])[0]||'',sourceType,sourceUrl,
      mediaDataUrl:thumb,captureId:activeInbox.captureId
    });
    await vault('/knowledge-idea-inbox/update',{method:'POST',body:{id:activeInbox.id,status:'done'}});
    $('#inboxDialog').close();activeInbox=null;
    await loadWorkspace();
    notice('Capture in den Ideenspeicher übernommen. Das lokale Original bleibt erhalten.');
  }catch(err){notice(err.message,'warn')}
}
function detectSource(url){try{const h=new URL(String(url||'')).hostname.toLowerCase();if(h.includes('reddit.com'))return'reddit';if(h.includes('youtube.com')||h.includes('youtu.be'))return'youtube';if(h)return'web'}catch(_){ }return''}
function resetQuickIdea(){quickAttachment={mediaDataUrl:'',name:'',type:'',text:''};$('#quickIdeaForm')?.reset();const a=$('#quickIdeaAttachment');if(a){a.hidden=true;a.innerHTML=''}}
function closeQuickIdea(){resetQuickIdea();$('#quickIdeaDialog')?.close()}
function renderQuickAttachment(){const a=$('#quickIdeaAttachment');if(!a)return;if(!quickAttachment.mediaDataUrl&&!quickAttachment.text&&!quickAttachment.name){a.hidden=true;a.innerHTML='';return}const image=quickAttachment.mediaDataUrl?`<img src="${esc(quickAttachment.mediaDataUrl)}" alt="Anhang">`:`<div class="quick-file-icon">${quickAttachment.type==='text'?'T':'↗'}</div>`;const label=quickAttachment.name|| (quickAttachment.type==='text'?'Eingefügter Text':'Eingefügter Inhalt');const detail=quickAttachment.mediaDataUrl?'Screenshot / Bild':quickAttachment.type==='text'?'Text übernommen':'Fundstück';a.innerHTML=`${image}<div><strong>${esc(label)}</strong><small>${esc(detail)}</small></div><button type="button" data-quick-remove aria-label="Anhang entfernen">×</button>`;a.hidden=false;a.querySelector('[data-quick-remove]').onclick=()=>{quickAttachment={mediaDataUrl:'',name:'',type:'',text:''};renderQuickAttachment()}}
async function imageToDataUrl(file){const raw=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=raw});const max=1500,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.82)}
async function absorbQuickFile(file){if(!file)return;if(file.type.startsWith('image/')){quickAttachment={mediaDataUrl:await imageToDataUrl(file),name:file.name||'Screenshot',type:'image',text:''};renderQuickAttachment();return}if(file.type.startsWith('text/')||/\.txt$/i.test(file.name||'')){const t=await file.text();quickAttachment={mediaDataUrl:'',name:file.name||'Text',type:'text',text:t.slice(0,20000)};if(!$('#quickIdeaBody').value.trim())$('#quickIdeaBody').value=quickAttachment.text;renderQuickAttachment();return}notice('Für den direkten Capture werden derzeit Screenshots/Bilder und Textdateien unterstützt. Links und Text können zusätzlich eingefügt werden.','warn')}
function absorbQuickText(text){const t=String(text||'').trim();if(!t)return;try{const u=new URL(t);$('#quickIdeaUrl').value=u.href;const src=detectSource(u.href);if(src)$('#quickIdeaSource').value=src;quickAttachment={mediaDataUrl:'',name:u.hostname,type:'link',text:''};renderQuickAttachment();return}catch(_){ }if(!$('#quickIdeaBody').value.trim())$('#quickIdeaBody').value=t;else $('#quickIdeaBody').value+='\n\n'+t;quickAttachment={mediaDataUrl:'',name:'Eingefügter Text',type:'text',text:t};renderQuickAttachment()}
async function quickIdea(e){e.preventDefault();let title=$('#quickIdeaTitle').value.trim(),body=$('#quickIdeaBody').value.trim(),sourceType=$('#quickIdeaSource').value,sourceUrl=$('#quickIdeaUrl').value.trim();const inferred=detectSource(sourceUrl);if(inferred&&sourceType==='own')sourceType=inferred;const hasAny=!!(title||body||sourceUrl||quickAttachment.mediaDataUrl||quickAttachment.text||quickAttachment.name);if(!hasAny){notice('Füge einen Screenshot, Link, Text oder Gedanken hinzu. Mehr braucht eine Idee nicht.','warn');return}if(!title){const candidate=(body||quickAttachment.text||quickAttachment.name||sourceUrl||'Neue Idee').replace(/\s+/g,' ').trim();title=(candidate.slice(0,76)||'Neue Idee')+(candidate.length>76?' …':'')}try{const sources=[];if(sourceUrl)sources.push({label:sourceType,url:sourceUrl});if(quickAttachment.name&&!sourceUrl)sources.push({label:quickAttachment.name,url:''});const saved=await postCloud('/admin/knowledge/save',{itemType:'idea',title,contentHtml:body?'<p>'+esc(body).replace(/\n\n+/g,'</p><p>').replace(/\n/g,'<br>')+'</p>':'',excerpt:(body||quickAttachment.text||'').slice(0,500),sources});await postCloud('/admin/knowledge/meta',{itemId:saved.item.id,kind:'idea',stage:'ideas',sourceType,sourceUrl,mediaDataUrl:quickAttachment.mediaDataUrl||''});closeQuickIdea();await loadWorkspace();queueKnowledgeAnalysis(Number(saved.item.id),'new-idea');notice('Idee gespeichert. Lokale KI analysiert sie im Hintergrund.')}catch(err){notice(err.message,'warn')}}
function sourceKindFromUrl(url,label=''){const u=String(url||'').toLowerCase(),l=String(label||'').toLowerCase();if(u.includes('reddit.com')||l.includes('reddit')||l.includes('forum'))return'reddit';if(u.includes('youtube.com')||u.includes('youtu.be')||l.includes('youtube'))return'youtube';if(/paper|doi|journal|studie|artikel/.test(l))return'paper';if(/buch|book/.test(l))return'book';if(/screenshot|bild|image/.test(l))return'image';if(!url)return'own';return'web'}
function renderDetailTags(){const value=String($('#detailTags')?.value||''),tags=value.split(',').map(x=>x.trim()).filter(Boolean);const cluster=$('#detailCluster')?.value.trim()||'';const html=[cluster,...tags].filter(Boolean).map(t=>`<span class="tag">${esc(t)}</span>`).join('');if($('#detailTagPreview'))$('#detailTagPreview').innerHTML=html;if($('#detailTagStrip'))$('#detailTagStrip').innerHTML=html}
function renderDetailSources(){const host=$('#detailSources');if(!host||!activeItem)return;const m=mfor(activeItem.id),linked=(m.sourceIds||[]).map(sid=>items.find(x=>Number(x.id)===Number(sid))).filter(Boolean).map(x=>({internal:true,id:x.id,label:x.title,url:mfor(x.id).sourceUrl||'',kind:mfor(x.id).sourceType||'own'}));const external=detailSourcesDraft.map((x,i)=>({...x,index:i}));const rows=[...linked,...external];host.innerHTML=rows.length?rows.map(x=>{const kind=x.kind||sourceKindFromUrl(x.url,x.label),label=x.label||x.url||'Quelle';return `<article class="rich-source-card"><div class="rich-source-icon">${svgIcon(sourceInfo(kind).icon)}</div><div><strong>${esc(label)}</strong><small>${esc(x.internal?'Verknüpfte Idee / Capture':(x.url||sourceInfo(kind).label))}</small></div>${x.internal?'<span></span>':`<button type="button" data-remove-source="${x.index}" title="Quelle entfernen">×</button>`}</article>`}).join(''):'<div class="kh-empty compact">Noch keine Quellen verknüpft.</div>';host.querySelectorAll('[data-remove-source]').forEach(b=>b.onclick=()=>{detailSourcesDraft.splice(Number(b.dataset.removeSource),1);renderDetailSources()})}
function renderDetailTimeline(){const host=$('#detailTimeline');if(!host||!activeItem)return;const m=mfor(activeItem.id),events=[];if(activeItem.createdAt)events.push({at:activeItem.createdAt,title:'Idee angelegt',detail:m.captureId?'Aus Capture übernommen':'Im Knowledge Hub erfasst'});if((m.sourceIds||[]).length)events.push({at:activeItem.updatedAt||activeItem.createdAt,title:`${m.sourceIds.length} Quellen verbunden`,detail:m.kind==='concept'?'Concept aus mehreren Inspirationen entwickelt':'Quellen verknüpft'});if(m.kind==='concept')events.push({at:activeItem.updatedAt||activeItem.createdAt,title:'Concept entwickelt',detail:'Mehrere Gedanken wurden zu einem gemeinsamen Arbeitskonzept verbunden'});if(activeItem.itemType==='article')events.push({at:activeItem.updatedAt,title:'Als Artikel entwickelt',detail:'Longform-Entwurf angelegt'});if(m.stage&&m.stage!=='ideas')events.push({at:m.updatedAt||activeItem.updatedAt,title:'Workflow: '+({develop:'Entwickeln',production:'Produktion',review:'Review',scheduled:'Geplant',published:'Veröffentlicht'}[m.stage]||m.stage),detail:'Aktueller Pipeline-Status'});if(activeItem.publishedAt)events.push({at:activeItem.publishedAt,title:new Date(activeItem.publishedAt)>new Date()?'Veröffentlichung geplant':'Veröffentlicht',detail:activeItem.slug?`/wissen/?slug=${activeItem.slug}`:''});events.sort((a,b)=>new Date(a.at)-new Date(b.at));host.innerHTML=events.length?events.map(e=>`<div class="timeline-event"><span class="timeline-dot"></span><time>${esc(fmt(e.at))}</time><div><strong>${esc(e.title)}</strong><span>${esc(e.detail||'')}</span></div></div>`).join(''):'<div class="kh-empty compact">Noch keine Timeline-Ereignisse.</div>'}
function renderAnalysis(data){detailAnalysisCache=data||null;const host=$('#detailAnalysis');if(!host)return;if(!data){host.innerHTML='<div class="kh-empty">Noch keine Analyse erstellt. Neue Ideen und Concepts werden automatisch im Hintergrund analysiert.</div>';return}if(data.status==='pending'||data.status==='running'){host.innerHTML=`<div class="analysis-working">${svgIcon('i-sparkle')}<div><strong>Lokale KI analysiert …</strong><p class="kh-muted">Du kannst weiterarbeiten; die Vorschläge erscheinen automatisch.</p></div></div>`;return}if(data.status==='error'&&!data.commonCore){host.innerHTML=`<div class="kh-empty">Analyse ausstehend. ${esc(data.error||'Lokales Modell derzeit nicht erreichbar.')} Sie wird beim nächsten verfügbaren Vault erneut versucht.</div>`;return}const list=v=>(Array.isArray(v)&&v.length)?`<ul>${v.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>—</p>';const suggestedTags=uniqueTags(data.suggestedTags||[]),suggestedFormats=uniqueTags((data.suggestedFormats||[]).map(normalizeFormatSuggestion).filter(Boolean));const tagHtml=suggestedTags.length?`<div class="suggestion-chip-row">${suggestedTags.map(t=>`<button type="button" class="suggestion-chip" data-ai-tag="${esc(t)}">${esc(t)}</button>`).join('')}</div><button type="button" class="kh-soft compact-action" id="acceptAllAiTags">Alle Tags übernehmen</button>`:'<p>—</p>';const clusterHtml=data.suggestedCluster?`<div class="ai-cluster-suggestion"><span>${esc(data.suggestedCluster)}</span><button type="button" class="kh-soft compact-action" id="acceptAiCluster">Als Thema übernehmen</button></div>`:'<p>—</p>';const formatHtml=suggestedFormats.length?`<div class="ai-format-suggestions">${suggestedFormats.map(k=>{const f=formats.find(x=>x[0]===k);return f?`<button type="button" class="ai-format-chip" data-ai-format="${k}">${svgIcon(f[2])}<span>${esc(f[1])}</span></button>`:''}).join('')}</div>`:'<p>—</p>';host.innerHTML=`<article class="analysis-card wide"><h4>Gemeinsamer Kern</h4><p>${esc(data.commonCore||'—')}</p></article><article class="analysis-card"><h4>Wiederkehrende Fragen</h4>${list(data.questions)}</article><article class="analysis-card"><h4>Spannungen / Gegenpositionen</h4>${list(data.tensions)}</article><article class="analysis-card"><h4>Vorgeschlagenes Thema</h4>${clusterHtml}</article><article class="analysis-card"><h4>Tag-Vorschläge</h4>${tagHtml}</article><article class="analysis-card"><h4>Mögliche Formate</h4>${formatHtml}</article><article class="analysis-card wide"><h4>Content-Potenzial</h4>${list(data.contentPotential)}</article>${data.model?`<article class="analysis-card wide"><p class="kh-muted">Lokal analysiert mit ${esc(data.model)} · ${esc(data.processingSeconds||'')} s</p></article>`:''}`;host.querySelectorAll('[data-ai-tag]').forEach(b=>b.onclick=()=>acceptSuggestedTags([b.dataset.aiTag]));$('#acceptAllAiTags')?.addEventListener('click',()=>acceptSuggestedTags(suggestedTags));$('#acceptAiCluster')?.addEventListener('click',()=>{if(data.suggestedCluster){$('#detailCluster').value=data.suggestedCluster;renderDetailTags()}});host.querySelectorAll('[data-ai-format]').forEach(b=>b.onclick=()=>{const cb=$(`#formatPicker input[value="${b.dataset.aiFormat}"]`);if(cb)cb.checked=true})}
function acceptSuggestedTags(tags){const existing=String($('#detailTags')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),merged=uniqueTags([...existing,...tags]);if($('#detailTags'))$('#detailTags').value=merged.join(', ');renderDetailTags()}
async function analyzeKnowledgeItem(itemId,{manual=false,reason='manual'}={}){const item=items.find(x=>Number(x.id)===Number(itemId));if(!item)throw new Error('Idee nicht gefunden.');const m=mfor(item.id),linked=(m.sourceIds||[]).map(sid=>items.find(x=>Number(x.id)===Number(sid))).filter(Boolean).map(x=>({label:x.title,url:mfor(x.id).sourceUrl||'',text:(plain(x.contentHtml)||x.excerpt||'').slice(0,4000)})),external=(item.sources||[]).map(x=>({label:x.label||'',url:x.url||'',text:''}));const running={...(m.analysis||{}),status:'running',reason,startedAt:new Date().toISOString()};await postCloud('/admin/knowledge/meta',{...m,itemId:item.id,analysis:running});meta[String(item.id)]={...m,analysis:running};if(activeItem&&Number(activeItem.id)===Number(item.id))renderAnalysis(running);const result=await vault('/knowledge/analyze',{method:'POST',body:{title:item.title||'',body:plain(item.contentHtml)||item.excerpt||'',cluster:m.cluster||item.category||'',tags:item.tags||[],sources:[...linked,...external]}});const analysis={...(result.analysis||{}),status:'done',reason,model:result.model||'',processingSeconds:result.processingSeconds||0,updatedAt:new Date().toISOString()};await postCloud('/admin/knowledge/meta',{...m,itemId:item.id,analysis});meta[String(item.id)]={...m,analysis};if(activeItem&&Number(activeItem.id)===Number(item.id))renderAnalysis(analysis);renderIdeas();return analysis}
async function runKnowledgeAnalysis(){if(!activeItem)return;const btn=$('#detailAnalyzeBtn');btn.disabled=true;btn.textContent='Lokale KI arbeitet …';try{await saveDetail(false);analysisQueue=analysisQueue.filter(x=>Number(x.itemId)!==Number(activeItem.id));await analyzeKnowledgeItem(activeItem.id,{manual:true,reason:'manual'});notice('Lokale KI-Analyse aktualisiert.')}catch(err){notice(err.message,'warn')}finally{btn.disabled=false;btn.textContent='Neu analysieren'}}
async function markAnalysisPending(itemId,reason){const item=items.find(x=>Number(x.id)===Number(itemId));if(!item)return;const m=mfor(itemId),old=m.analysis||{};if(old.status==='running'||(old.status==='pending'&&old.reason===reason))return;const pending={...old,status:'pending',reason,queuedAt:new Date().toISOString(),error:''};try{await postCloud('/admin/knowledge/meta',{...m,itemId,analysis:pending});meta[String(itemId)]={...m,analysis:pending};renderIdeas();if(activeItem&&Number(activeItem.id)===Number(itemId))renderAnalysis(pending)}catch(_){ }}
function queueKnowledgeAnalysis(itemId,reason='background'){itemId=Number(itemId);if(!itemId)return;if(!analysisQueue.some(x=>x.itemId===itemId))analysisQueue.push({itemId,reason});markAnalysisPending(itemId,reason).finally(()=>processAnalysisQueue());}
function resumePendingAnalyses(){for(const item of items){const a=mfor(item.id).analysis||{};if(a.status==='pending'||a.status==='running'||(a.status==='error'&&a.retry!==false)){if(!analysisQueue.some(x=>x.itemId===Number(item.id)))analysisQueue.push({itemId:Number(item.id),reason:a.reason||'resume'})}}processAnalysisQueue()}
async function processAnalysisQueue(){if(analysisRunning||!analysisQueue.length)return;analysisRunning=true;const job=analysisQueue.shift();let retry=false;try{await analyzeKnowledgeItem(job.itemId,{reason:job.reason})}catch(err){retry=true;const m=mfor(job.itemId),failed={...(m.analysis||{}),status:'error',reason:job.reason,error:String(err.message||err),updatedAt:new Date().toISOString()};try{await postCloud('/admin/knowledge/meta',{...m,itemId:job.itemId,analysis:failed});meta[String(job.itemId)]={...m,analysis:failed}}catch(_){ }if(activeItem&&Number(activeItem.id)===Number(job.itemId))renderAnalysis(failed)}finally{analysisRunning=false;if(analysisQueue.length){clearTimeout(analysisWakeTimer);analysisWakeTimer=setTimeout(processAnalysisQueue,900)}else if(retry){clearTimeout(analysisWakeTimer);analysisWakeTimer=setTimeout(()=>queueKnowledgeAnalysis(job.itemId,'retry'),120000)}}}
function openDetail(id){activeItem=items.find(x=>Number(x.id)===Number(id));if(!activeItem)return;const m=mfor(id);detailSourcesDraft=(activeItem.sources||[]).map(x=>({label:String(x.label||''),url:String(x.url||'')}));detailAnalysisCache=null;$('#detailKind').textContent=(m.kind||activeItem.itemType||'idee').toUpperCase();$('#detailHeading').textContent=activeItem.title||'Idee';$('#detailTitle').value=activeItem.title||'';$('#detailBody').value=plain(activeItem.contentHtml)||activeItem.excerpt||'';$('#detailCluster').value=m.cluster||activeItem.category||'';$('#detailTags').value=(activeItem.tags||[]).join(', ');$('#detailSourceUrl').value=m.sourceUrl||'';$('#detailNotes').value=m.notes||'';$('#detailStage').value=stageFor(activeItem)==='published'?'review':stageFor(activeItem);$('#detailDue').value=m.dueAt?String(m.dueAt).slice(0,16):'';$('#formatPicker').innerHTML=formats.map(([key,label,iconId])=>`<label class="format-option"><input type="checkbox" value="${key}" ${(m.formats||[]).includes(key)?'checked':''}><span class="format-visual">${svgIcon(iconId,'format-icon')}<strong>${esc(label)}</strong></span></label>`).join('');renderDetailTags();renderDetailSources();renderDetailTimeline();renderAnalysis(m.analysis&&Object.keys(m.analysis).length?m.analysis:null);if($('#articleRichEditor'))$('#articleRichEditor').innerHTML=activeItem.contentHtml||'';if($('#developArticleBtn')){$('#developArticleBtn').hidden=activeItem.itemType==='article';$('#developArticleBtn').textContent=m.kind==='concept'?'Concept als Artikel entwickeln':'Als Artikel entwickeln'}if($('#detailSlug'))$('#detailSlug').value=activeItem.slug||'';if($('#detailCategory'))$('#detailCategory').value=activeItem.category||'';if($('#detailSeoTitle'))$('#detailSeoTitle').value=activeItem.seoTitle||'';if($('#detailSeoDescription'))$('#detailSeoDescription').value=activeItem.seoDescription||'';const future=activeItem.status==='published'&&activeItem.publishedAt&&new Date(activeItem.publishedAt)>new Date();if($('#detailPublishMode'))$('#detailPublishMode').value=future?'scheduled':'now';if($('#detailPublishDate'))$('#detailPublishDate').value=future?String(activeItem.publishedAt).slice(0,16):'';if($('#detailPublishDateWrap'))$('#detailPublishDateWrap').hidden=!future;if($('#detailUnpublishBtn'))$('#detailUnpublishBtn').hidden=activeItem.status!=='published';if($('#detailPublishBtn')){$('#detailPublishBtn').hidden=activeItem.status==='archived';$('#detailPublishBtn').textContent=future?'Veröffentlichung aktualisieren':'Veröffentlichen'}if($('#detailPublishHint'))$('#detailPublishHint').textContent=activeItem.itemType==='article'?'Veröffentlicht wird nur nach ausdrücklicher Bestätigung.':'Vor dem Veröffentlichen zuerst als Artikel entwickeln.';if($('#detailArchiveBtn')){$('#detailArchiveBtn').innerHTML=activeItem.status==='archived'?`${svgIcon('i-restore')}<span>Wiederherstellen</span>`:`${svgIcon('i-archive')}<span>Archivieren</span>`}if($('#detailDeleteBtn'))$('#detailDeleteBtn').hidden=activeItem.status==='published';if($('#detailMoreMenu'))$('#detailMoreMenu').hidden=true;if($('#detailMoreBtn'))$('#detailMoreBtn').setAttribute('aria-expanded','false');$$('.detail-tabs button').forEach((x,i)=>x.classList.toggle('active',i===0));$$('[data-detail-panel]').forEach(p=>p.hidden=p.dataset.detailPanel!=='overview');$('#detailDialog').showModal()}
async function saveDetail(close=true){if(!activeItem)return;const m=mfor(activeItem.id),title=$('#detailTitle').value.trim(),body=$('#detailBody').value.trim(),kind=m.kind||activeItem.itemType||'idea',article=activeItem.itemType==='article',content=article?String($('#articleRichEditor')?.innerHTML||activeItem.contentHtml||''):(body?'<p>'+esc(body).replace(/\n\n+/g,'</p><p>').replace(/\n/g,'<br>')+'</p>':'');try{const saved=await postCloud('/admin/knowledge/save',{id:activeItem.id,itemType:activeItem.itemType,title,subtitle:activeItem.subtitle||'',contentHtml:content,excerpt:body.slice(0,500),category:$('#detailCategory')?.value.trim()||activeItem.category||'',tags:String($('#detailTags')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),author:activeItem.author||'Theophil Kroller',sources:detailSourcesDraft,internalLinks:activeItem.internalLinks||[],faq:activeItem.faq||[],imageUrl:activeItem.imageUrl||'',seoTitle:$('#detailSeoTitle')?.value.trim()||'',seoDescription:$('#detailSeoDescription')?.value.trim()||'',visibleUntil:activeItem.visibleUntil||null,slug:$('#detailSlug')?.value.trim()||activeItem.slug||''});activeItem=saved.item;const formatsChosen=$$('#formatPicker input:checked').map(x=>x.value);await postCloud('/admin/knowledge/meta',{...m,itemId:activeItem.id,kind,stage:$('#detailStage').value,cluster:$('#detailCluster').value.trim(),sourceUrl:$('#detailSourceUrl').value.trim(),formats:formatsChosen,notes:$('#detailNotes').value,dueAt:$('#detailDue').value?new Date($('#detailDue').value).toISOString():''});if(close)$('#detailDialog').close();await loadWorkspace();if(!close)activeItem=items.find(x=>Number(x.id)===Number(saved.item.id))||saved.item;notice('Gespeichert.');return activeItem}catch(err){notice(err.message,'warn');throw err}}

async function detailAction(action,extra={}){if(!activeItem)return;const id=activeItem.id;try{if(!['delete'].includes(action))await saveDetail(false);const x=await postCloud('/admin/knowledge/action',{id,action,...extra});if(x.deleted){$('#detailDialog').close();await loadWorkspace();notice(x.unmergedCount?`Concept gelöscht. ${x.unmergedCount} Quellen sind wieder eigenständige Ideen.`:'Inhalt gelöscht.');return}activeItem=x.item;await loadWorkspace();if(action==='archive'||action==='restore'){$('#detailDialog').close();notice(action==='archive'?'Ins Archiv verschoben.':'Wiederhergestellt.');return}openDetail(activeItem.id);notice(action==='publish'?'Veröffentlichung gespeichert.':action==='unpublish'?'Veröffentlichung zurückgezogen.':'Inhalt aktualisiert.')}catch(err){notice(err.message,'warn')}}
